-- Descriptions of the three Trip reports.
UPDATE trips SET description = 'Emperors'' palaces, an army of clay warriors, pandas at breakfast, turquoise lakes in the mountains and stone pillars rising out of the mist. From the Great Wall to the Avatar mountains, in the soft spring light.' WHERE slug = 'china-360';
UPDATE trips SET description = 'The old Silk Road, where the land empties and the sky opens. Mirror-like salt lakes, painted caves at Mogao, dunes that glow at dusk and hills striped like rainbows.' WHERE slug = 'qinghai-gansu';
UPDATE trips SET description = 'From the neon harbour of Hong Kong to the edge of Tibet. Through a forest of stones, lakeside pagodas and canal towns, up to where the monasteries sit above the clouds.' WHERE slug = 'yunnan-winter';
